          "contact.reportTitle": "Nahlášení nezákonného obsahu a rozhodnutí o moderování",
          "contact.reportText": "Napište na rentulo@rentulo.com. Uveďte odkaz na nabídku, přesný důvod a vysvětlení, proč ji považujete za nezákonnou, své kontaktní údaje (pokud je zákon nevyjímá) a prohlášení, že oznámení podáváte v dobré víře. Na stejnou adresu lze zaslat námitku proti rozhodnutí.",
