          "contact.operatorTitle": "Prevádzkovateľ Rentulo",
          "contact.operatorNotice": "Identifikačné údaje prevádzkovateľa budú doplnené pred spustením ostrej prevádzky. Nasledujúce položky zatiaľ slúžia iba ako pripravená štruktúra stránky.",
          "contact.companyLabel": "Názov spoločnosti",
          "contact.addressLabel": "Sídlo",
          "contact.addressValue": "Rybničná 11, 831 07 Bratislava, Slovenská republika",
          "contact.companyIdLabel": "IČO",
          "contact.taxIdLabel": "DIČ",
          "contact.registerLabel": "Zápis v registri",
          "contact.registerValue": "Mestský súd Bratislava III, oddiel Sro, vložka č. 75181/B",
          "contact.helpKicker": "Keď riešite rezerváciu",
          "contact.helpTitle": "Pomôžte nám nájsť správny prípad",
          "contact.helpText": "Napíšte nám z e-mailovej adresy, ktorú používate v Rentulo, a ak je to možné, pridajte číslo alebo iné údaje konkrétnej rezervácie.",
          "contact.reportTitle": "Nahlásenie nezákonného obsahu a rozhodnutia o moderovaní",
          "contact.reportText": "Napíšte na rentulo@rentulo.com. Uveďte odkaz na ponuku, presný dôvod nezákonnosti, kontaktné údaje (ak ich zákon nevyžaduje vynechať) a vyhlásenie, že oznámenie podávate v dobrej viere. Na tú istú adresu možno podať námietku proti rozhodnutiu.",
