          "detail.documentTitle": "Angebotsdetails - Rentulo",
          "detail.privateListingNote": "Privates Angebot laut Erklärung des Eigentümers. Bei einer Vermietung zwischen Privatpersonen gelten in der Regel nicht dieselben Verbraucherrechte wie bei einem Vertrag mit einem Unternehmen.",
