          "settings.cancelAccountRetentionNote": "Historische Daten zu abgeschlossenen Reservierungen, Zahlungen und Bewertungen können so lange gespeichert bleiben, wie dies für rechtliche, buchhalterische oder sicherheitsbezogene Pflichten erforderlich ist.",
