          "reservations.paymentModal.noShowWarning": "Ważne: Jednorazowy PIN można wykorzystać do przekazania od 2 godzin przed uzgodnioną godziną odbioru aż do uzgodnionej godziny zwrotu, czyli ostatniego dnia do tej samej godziny (Europe/Prague). Po potwierdzeniu przekazania PIN natychmiast traci ważność, a termin zwrotu nie ulega zmianie. Jeżeli nie odbierzesz rzeczy przed uzgodnioną godziną zwrotu, PIN wygaśnie, rezerwacja zostanie zamknięta podczas najbliższego automatycznego przetwarzania, a Stripe otrzyma polecenie wypłaty właścicielowi. Płatność nie jest automatycznie zwracana, ale można zgłosić uzasadniony problem z przekazaniem.",
