          "contact.operatorNotice": "Dane identyfikacyjne operatora zostaną uzupełnione przed uruchomieniem produkcyjnym. Poniższe pola służą obecnie wyłącznie jako przygotowana struktura tej strony.",
          "contact.companyLabel": "Nazwa firmy",
          "contact.addressLabel": "Siedziba",
          "contact.addressValue": "Rybničná 11, 831 07 Bratislava, Słowacja",
