          "contact.taxIdLabel": "Numer identyfikacji podatkowej (DIČ)",
          "contact.registerLabel": "Wpis do rejestru",
          "contact.registerValue": "Mestský súd Bratislava III, dział Sro, nr wpisu 75181/B",
          "contact.helpKicker": "Gdy sprawa dotyczy rezerwacji",
