          "contact.helpText": "Napisz do nas z adresu e-mail używanego w Rentulo i, jeśli to możliwe, podaj numer rezerwacji lub inne dane dotyczące konkretnej rezerwacji.",
          "contact.reportTitle": "Zgłaszanie nielegalnych treści i odwołania od moderacji",
          "contact.reportText": "Napisz na rentulo@rentulo.com, podając link do oferty, konkretny powód uznania treści za nielegalną, dane kontaktowe (o ile są wymagane) oraz oświadczenie o działaniu w dobrej wierze. Pod tym adresem można też odwołać się od decyzji moderacyjnej.",
